import csv


def _read_csv(path):
    with open(path, 'r', encoding='utf-8-sig', newline='') as f:
        return {row['invoice_id']: row for row in csv.DictReader(f)}


def diagnose(backup_path, checkpoint_path, current_path, context):
    backup = _read_csv(backup_path)
    checkpoint = _read_csv(checkpoint_path)
    current = _read_csv(current_path)

    # The incident multiplied prices by 100; only the price column changed
    # between backup and checkpoint. Payment_status changes happened later
    # and must be kept, so they are not touched.
    affected_columns = ['price']

    cells = []
    for key in backup:
        if key not in checkpoint or key not in current:
            continue
        before = backup[key]
        after = checkpoint[key]
        for col in affected_columns:
            if before.get(col) != after.get(col):
                cells.append({
                    'key': {'type': 'text', 'value': key},
                    'column': col,
                })
                if len(cells) >= 1000:
                    break
        if len(cells) >= 1000:
            break

    summary = (
        "The bad import multiplied the price column by 100 for all 120 records "
        "that existed at the time; comparing the last good backup with the "
        "checkpoint right after the import confirmed price changed on every "
        "record while customer, payment_status and created_on did not change "
        "during the incident. The proposed cells revert price on records "
        "present in all three versions, excluding the 7 records created after "
        "the incident and any record missing today. Records whose price was "
        "edited again after the incident are still included because the "
        "controller independently protects overlaps. Later payment_status "
        "updates are left untouched, and no files were modified."
    )
    return {'cells': cells, 'summary': summary}

