import csv, shutil, sqlite3

def _qident(name):
    return '"' + str(name).replace('"', '""') + '"'

def recover(backup_path, current_path, output_path, scope):
    fmt = scope.get('format')
    pk = scope['primary_key']
    cells = scope.get('cells') or []

    if fmt == 'csv':
        with open(current_path, 'r', encoding='utf-8-sig', newline='') as f:
            reader = csv.DictReader(f)
            fieldnames = list(reader.fieldnames or [])
            rows = list(reader)
        with open(backup_path, 'r', encoding='utf-8-sig', newline='') as f:
            backup_rows = {}
            for r in csv.DictReader(f):
                k = r.get(pk)
                if k is not None and k not in backup_rows:
                    backup_rows[k] = r

        for cell in cells:
            key = cell['key']
            kval = key['value']
            if key['type'] == 'integer':
                kval = str(int(kval))
            col = cell['column']
            if kval in backup_rows and col in backup_rows[kval] and col in fieldnames:
                for row in rows:
                    if row.get(pk) == kval:
                        row[col] = backup_rows[kval][col]
                        break

        with open(output_path, 'w', encoding='utf-8', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction='ignore')
            writer.writeheader()
            for row in rows:
                writer.writerow({c: row.get(c, '') for c in fieldnames})

    elif fmt == 'sqlite':
        shutil.copyfile(current_path, output_path)
        src = sqlite3.connect('file:' + backup_path.replace('?', '%3f') + '?mode=ro&immutable=1', uri=True)
        dst = sqlite3.connect(output_path)
        try:
            for cell in cells:
                key = cell['key']
                kval = key['value']
                if key['type'] == 'integer':
                    kval = int(kval)
                col = cell['column']
                table = scope.get('table') or 'records'
                cur = src.execute(
                    'SELECT ' + _qident(col) + ' FROM ' + _qident(table) +
                    ' WHERE ' + _qident(pk) + ' = ?', (kval,))
                got = cur.fetchone()
                if got is not None:
                    dst.execute(
                        'UPDATE ' + _qident(table) + ' SET ' + _qident(col) +
                        ' = ? WHERE ' + _qident(pk) + ' = ?', (got[0], kval))
            dst.commit()
        finally:
            dst.close()
            src.close()
    else:
        raise ValueError('unsupported format: %r' % (fmt,))
